CREATE POLICY homeowner_book_visibility_select ON public.lender_portfolio_clients AS RESTRICTIVE FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.lender_portfolios p WHERE p.id=portfolio_id AND public.lender_book_visible(auth.uid(),p.lender_org_id,p.assigned_user_id)));
CREATE POLICY homeowner_book_visibility_update ON public.lender_portfolio_clients AS RESTRICTIVE FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.lender_portfolios p WHERE p.id=portfolio_id AND public.lender_book_visible(auth.uid(),p.lender_org_id,p.assigned_user_id))) WITH CHECK (EXISTS (SELECT 1 FROM public.lender_portfolios p WHERE p.id=portfolio_id AND public.lender_book_visible(auth.uid(),p.lender_org_id,p.assigned_user_id)));
CREATE POLICY homeowner_book_visibility_delete ON public.lender_portfolio_clients AS RESTRICTIVE FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.lender_portfolios p WHERE p.id=portfolio_id AND public.lender_book_visible(auth.uid(),p.lender_org_id,p.assigned_user_id)));